// Minimal zero-dependency static server for local development: `npm start`.
// Serves ./site on http://localhost:5173 (override with PORT).
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, normalize, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(fileURLToPath(new URL('../site/', import.meta.url)));
const PORT = Number(process.env.PORT) || 5173;
const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, 'http://localhost');
    let file = normalize(join(ROOT, decodeURIComponent(pathname)));
    if (file !== ROOT && !file.startsWith(ROOT + sep)) {
      res.writeHead(403).end('Forbidden');
      return;
    }
    if ((await stat(file).catch(() => null))?.isDirectory()) file = join(file, 'index.html');
    const body = await readFile(file);
    res.writeHead(200, {
      'Content-Type': TYPES[extname(file)] || 'application/octet-stream',
      'Cache-Control': 'no-store',
    });
    res.end(body);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain' }).end('Not found');
  }
}).listen(PORT, () => {
  console.log(`Bounce Lab running at http://localhost:${PORT}`);
});

// @ts-check
// Ball colors: four base hues, each with 10 shades whose RGB channels are
// scaled by -5%..+5% (capped at 255), so neighbouring balls never look identical.

/** @type {ReadonlyArray<{ name: string, base: string, shades: readonly string[] }>} */
export const COLOR_FAMILIES = Object.freeze([
  {
    name: 'red',
    base: '#F25022',
    shades: ['#E64C20', '#E94D21', '#EB4E21', '#EE4F21', '#F15022', '#F35022', '#F65123', '#F95223', '#FB5323', '#FE5424'],
  },
  {
    name: 'green',
    base: '#7FBA00',
    shades: ['#79B100', '#7AB300', '#7BB500', '#7DB700', '#7EB900', '#80BB00', '#81BD00', '#83BF00', '#84C100', '#85C300'],
  },
  {
    name: 'blue',
    base: '#00A4EF',
    shades: ['#009CE3', '#009EE6', '#009FE8', '#00A1EB', '#00A3EE', '#00A5F0', '#00A7F3', '#00A9F6', '#00AAF8', '#00ACFB'],
  },
  {
    name: 'yellow',
    base: '#FFB900',
    shades: ['#F2B000', '#F5B200', '#F8B400', '#FBB600', '#FEB800', '#FFBA00', '#FFBC00', '#FFBE00', '#FFC000', '#FFC200'],
  },
]);

/** All 40 shades, flattened. */
export const PALETTE = Object.freeze(COLOR_FAMILIES.flatMap((f) => f.shades));

/**
 * Pick a random shade.
 * @param {() => number} [rng]
 */
export function randomColor(rng = Math.random) {
  return PALETTE[Math.floor(rng() * PALETTE.length) % PALETTE.length];
}

/**
 * @param {string} hex like "#AABBCC"
 * @returns {[number, number, number]}
 */
export function hexToRgb(hex) {
  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
  if (!m) throw new Error(`Invalid hex color: ${hex}`);
  return [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)];
}

// @ts-check
// Simulation settings: defaults, limits, gravity presets, and URL (hash) round-tripping
// so a configuration can be shared as a link.

/**
 * @typedef {object} Settings
 * @property {number} gravity     m/s²
 * @property {number} bounciness  coefficient of restitution, 0.3–1
 * @property {number} airDrag     fraction of speed lost per second, 0–0.5
 * @property {number} ballSize    average ball radius in CSS pixels
 * @property {number} startCount  balls spawned on reset
 */

/** Surface gravity of a few bodies, in m/s². */
export const GRAVITY_PRESETS = Object.freeze([
  { id: 'zero-g', label: 'Zero-G', gravity: 0 },
  { id: 'moon', label: 'Moon', gravity: 1.62 },
  { id: 'mars', label: 'Mars', gravity: 3.71 },
  { id: 'earth', label: 'Earth', gravity: 9.81 },
  { id: 'jupiter', label: 'Jupiter', gravity: 24.79 },
]);

/** @type {Readonly<Record<keyof Settings, { min: number, max: number, step: number }>>} */
export const LIMITS = Object.freeze({
  gravity: { min: 0, max: 25, step: 0.01 },
  bounciness: { min: 0.3, max: 1, step: 0.01 },
  airDrag: { min: 0, max: 0.5, step: 0.01 },
  ballSize: { min: 8, max: 40, step: 1 },
  startCount: { min: 1, max: 100, step: 1 },
});

/** @type {Readonly<Settings>} */
export const DEFAULTS = Object.freeze({
  gravity: 1.62, // the Moon
  bounciness: 0.85,
  airDrag: 0.02,
  ballSize: 20,
  startCount: 12,
});

// Short keys keep shared URLs tidy.
/** @type {Readonly<Record<keyof Settings, string>>} */
const HASH_KEYS = Object.freeze({
  gravity: 'g',
  bounciness: 'e',
  airDrag: 'd',
  ballSize: 's',
  startCount: 'n',
});

/**
 * Clamp a value into the setting's range and snap it to the step.
 * Returns the default for anything that is not a finite number.
 * @param {keyof Settings} key
 * @param {unknown} value
 */
export function clampSetting(key, value) {
  const { min, max, step } = LIMITS[key];
  const n = typeof value === 'string' && value.trim() === '' ? NaN : Number(value);
  if (!Number.isFinite(n)) return DEFAULTS[key];
  const snapped = Math.round(n / step) * step;
  const decimals = (String(step).split('.')[1] || '').length;
  return Number(Math.min(max, Math.max(min, snapped)).toFixed(decimals));
}

/**
 * @param {Partial<Record<keyof Settings, unknown>>} [partial]
 * @returns {Settings}
 */
export function normalizeSettings(partial = {}) {
  /** @type {any} */
  const out = {};
  for (const key of /** @type {(keyof Settings)[]} */ (Object.keys(DEFAULTS))) {
    out[key] = key in partial ? clampSetting(key, partial[key]) : DEFAULTS[key];
  }
  return out;
}

/**
 * Read settings from a location hash such as "#g=9.81&e=0.9".
 * Unknown keys are ignored; invalid values fall back to defaults.
 * @param {string} hash
 * @returns {Settings}
 */
export function settingsFromHash(hash) {
  const params = new URLSearchParams(hash.replace(/^#/, ''));
  /** @type {Partial<Record<keyof Settings, unknown>>} */
  const partial = {};
  for (const [key, short] of Object.entries(HASH_KEYS)) {
    if (params.has(short)) partial[/** @type {keyof Settings} */ (key)] = params.get(short);
  }
  return normalizeSettings(partial);
}

/**
 * Encode only the settings that differ from the defaults, so the default view has a clean URL.
 * @param {Settings} settings
 * @returns {string} hash including "#", or "" when everything is default
 */
export function settingsToHash(settings) {
  const params = new URLSearchParams();
  for (const [key, short] of Object.entries(HASH_KEYS)) {
    const k = /** @type {keyof Settings} */ (key);
    const v = clampSetting(k, settings[k]);
    if (v !== DEFAULTS[k]) params.set(short, String(v));
  }
  const s = params.toString();
  return s ? `#${s}` : '';
}

/**
 * The preset whose gravity matches exactly, if any.
 * @param {number} gravity
 */
export function presetForGravity(gravity) {
  return GRAVITY_PRESETS.find((p) => Math.abs(p.gravity - gravity) < 1e-9) || null;
}

// @ts-check
// Bounce Lab physics. Pure and DOM-free so it can be unit tested in Node.
//
// Units: positions in CSS pixels, time in seconds. Gravity comes in as m/s² and is
// converted with PX_PER_METER. The world runs at a fixed timestep for stable,
// frame-rate-independent results.

import { randomColor } from './palette.js';
import { DEFAULTS } from './settings.js';

/** @typedef {import('./settings.js').Settings} Settings */

/** On-screen pixels per simulated meter. */
export const PX_PER_METER = 140;
/** Fixed simulation step (240 Hz). */
export const FIXED_DT = 1 / 240;
/** Hard cap on the number of balls, to keep the page responsive. */
export const MAX_BALLS = 300;
/** Upper bound on any ball's speed, in px/s. */
export const MAX_SPEED = 5000;
/** Most simulation time we'll catch up on in one frame (e.g. after a hitch). */
const MAX_FRAME_TIME = 0.1;
/** Fraction of horizontal speed kept per second while rolling on the floor. */
const FLOOR_GRIP = 0.5;
/** Overlap tolerated before positional correction kicks in (px). */
const SLOP = 0.05;

/**
 * @typedef {object} Ball
 * @property {number} id
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} r
 * @property {number} invMass 0 means immovable (used while a ball is held)
 * @property {string} color
 * @property {number} squash      0..0.35, visual deformation after an impact
 * @property {number} squashAngle direction of the last impact normal (radians)
 */

export class World {
  /**
   * @param {{ width: number, height: number, settings?: Partial<Settings>, rng?: () => number }} options
   */
  constructor({ width, height, settings = {}, rng = Math.random }) {
    this.width = Math.max(0, width);
    this.height = Math.max(0, height);
    /** @type {Settings} */
    this.settings = { ...DEFAULTS, ...settings };
    this.rng = rng;
    /** @type {Ball[]} */
    this.balls = [];
    this.nextId = 1;
    /** @type {null | { ball: Ball, dx: number, dy: number, tx: number, ty: number, vx: number, vy: number, t: number }} */
    this.held = null;
    this.accumulator = 0;
  }

  /** @param {Partial<Settings>} settings */
  setSettings(settings) {
    this.settings = { ...this.settings, ...settings };
  }

  /**
   * Resize the world, keeping every ball inside it.
   * @param {number} width
   * @param {number} height
   */
  setSize(width, height) {
    this.width = Math.max(0, width);
    this.height = Math.max(0, height);
    for (const b of this.balls) this.#keepInside(b);
  }

  /**
   * @param {{ x: number, y: number, vx?: number, vy?: number, r?: number, color?: string }} init
   * @returns {Ball}
   */
  addBall({ x, y, vx = 0, vy = 0, r, color }) {
    const radius = r ?? this.#randomRadius();
    /** @type {Ball} */
    const ball = {
      id: this.nextId++,
      x,
      y,
      vx,
      vy,
      r: radius,
      invMass: 1 / (radius * radius),
      color: color ?? randomColor(this.rng),
      squash: 0,
      squashAngle: 0,
    };
    this.#keepInside(ball);
    this.balls.push(ball);
    // Drop the oldest ball that isn't being held.
    while (this.balls.length > MAX_BALLS) {
      const i = this.balls.findIndex((b) => b !== this.held?.ball);
      this.balls.splice(i, 1);
    }
    return ball;
  }

  /**
   * Scatter `count` balls across the upper part of the world with a little sideways motion.
   * @param {number} count
   */
  spawn(count) {
    for (let i = 0; i < count; i++) {
      const r = this.#randomRadius();
      this.addBall({
        x: r + this.rng() * Math.max(0, this.width - 2 * r),
        y: r + this.rng() * Math.max(0, this.height * 0.4 - r),
        vx: (this.rng() - 0.5) * 400,
        vy: (this.rng() - 0.5) * 200,
        r,
      });
    }
  }

  /** Remove every ball. */
  clear() {
    this.balls = [];
    this.held = null;
  }

  /** Clear and re-spawn the configured starting set. */
  reset() {
    this.clear();
    this.spawn(this.settings.startCount);
  }

  /**
   * Kick every ball upward and sideways.
   * @param {number} [strength] px/s
   */
  shake(strength = 900) {
    for (const b of this.balls) {
      if (b === this.held?.ball) continue;
      b.vx += (this.rng() - 0.5) * strength;
      b.vy -= strength * (0.5 + this.rng() * 0.5);
    }
  }

  /**
   * Topmost ball under a point, if any.
   * @param {number} x
   * @param {number} y
   */
  ballAt(x, y) {
    for (let i = this.balls.length - 1; i >= 0; i--) {
      const b = this.balls[i];
      if ((b.x - x) ** 2 + (b.y - y) ** 2 <= b.r * b.r) return b;
    }
    return null;
  }

  /**
   * Start dragging a ball. While held it follows the pointer and pushes others aside.
   * @param {Ball} ball
   * @param {number} x
   * @param {number} y
   * @param {number} t time in seconds (e.g. performance.now() / 1000)
   */
  grab(ball, x, y, t) {
    // Bring it to the front so it draws above the rest.
    this.balls.splice(this.balls.indexOf(ball), 1);
    this.balls.push(ball);
    ball.invMass = 0;
    this.held = { ball, dx: ball.x - x, dy: ball.y - y, tx: ball.x, ty: ball.y, vx: 0, vy: 0, t };
  }

  /**
   * Move the held ball's target, tracking a smoothed pointer velocity for the throw.
   * @param {number} x
   * @param {number} y
   * @param {number} t seconds
   */
  dragTo(x, y, t) {
    const h = this.held;
    if (!h) return;
    const tx = x + h.dx;
    const ty = y + h.dy;
    const dt = t - h.t;
    if (dt > 1e-4) {
      const k = Math.min(1, dt / 0.05); // ~50ms smoothing window
      h.vx += ((tx - h.tx) / dt - h.vx) * k;
      h.vy += ((ty - h.ty) / dt - h.vy) * k;
      h.t = t;
    }
    h.tx = tx;
    h.ty = ty;
  }

  /**
   * Let go of the held ball, throwing it with the pointer's recent velocity.
   * @param {number} [t] seconds; if the pointer has been still for a while, the throw is soft
   */
  release(t) {
    const h = this.held;
    if (!h) return;
    const idle = t === undefined ? 0 : t - h.t;
    const keep = idle > 0.1 ? 0 : 1;
    h.ball.vx = clampSpeed(h.vx * keep);
    h.ball.vy = clampSpeed(h.vy * keep);
    h.ball.invMass = 1 / (h.ball.r * h.ball.r);
    this.held = null;
  }

  /**
   * Advance by real elapsed time using fixed steps. Returns the number of steps run.
   * @param {number} elapsed seconds since the previous call
   */
  advance(elapsed) {
    this.accumulator = Math.min(this.accumulator + Math.max(0, elapsed), MAX_FRAME_TIME);
    let steps = 0;
    while (this.accumulator >= FIXED_DT) {
      this.step(FIXED_DT);
      this.accumulator -= FIXED_DT;
      steps++;
    }
    return steps;
  }

  /**
   * One simulation step.
   * @param {number} dt seconds
   */
  step(dt) {
    const { bounciness: e, airDrag } = this.settings;
    const g = this.settings.gravity * PX_PER_METER;
    const drag = Math.pow(1 - airDrag, dt);
    const grip = Math.pow(FLOOR_GRIP, dt);
    const settleSpeed = g * dt * 4 + 4;
    const squashDecay = Math.pow(0.0005, dt);

    for (const b of this.balls) {
      b.squash *= squashDecay;

      if (b === this.held?.ball) {
        b.vx = clampSpeed((this.held.tx - b.x) / dt);
        b.vy = clampSpeed((this.held.ty - b.y) / dt);
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        this.#keepInside(b);
        continue;
      }

      b.vy += g * dt;
      b.vx *= drag;
      b.vy *= drag;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      if (b.x - b.r < 0) {
        b.x = b.r;
        if (b.vx < 0) this.#bounce(b, -b.vx, Math.PI, e, 'x');
      } else if (b.x + b.r > this.width) {
        b.x = this.width - b.r;
        if (b.vx > 0) this.#bounce(b, b.vx, 0, e, 'x');
      }
      if (b.y - b.r < 0) {
        b.y = b.r;
        if (b.vy < 0) this.#bounce(b, -b.vy, -Math.PI / 2, e, 'y');
      } else if (b.y + b.r >= this.height) {
        b.y = this.height - b.r;
        if (b.vy > 0) this.#bounce(b, b.vy, Math.PI / 2, e, 'y');
        if (Math.abs(b.vy) < settleSpeed) b.vy = 0; // come to rest instead of buzzing
        b.vx *= grip;
      }
    }

    this.#collide(e);
  }

  /** Total kinetic energy (arbitrary units), useful for tests and debugging. */
  kineticEnergy() {
    let sum = 0;
    for (const b of this.balls) {
      if (b.invMass === 0) continue;
      sum += 0.5 * (1 / b.invMass) * (b.vx * b.vx + b.vy * b.vy);
    }
    return sum;
  }

  // Sweep-and-prune: sort by left edge, then only test balls whose x-extents overlap.
  /** @param {number} e */
  #collide(e) {
    const order = this.balls.slice().sort((a, b) => a.x - a.r - (b.x - b.r));
    for (let i = 0; i < order.length; i++) {
      const a = order[i];
      const right = a.x + a.r;
      for (let j = i + 1; j < order.length; j++) {
        const b = order[j];
        if (b.x - b.r > right) break;
        this.#resolve(a, b, e);
      }
    }
  }

  /**
   * @param {Ball} a
   * @param {Ball} b
   * @param {number} e
   */
  #resolve(a, b, e) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const minDist = a.r + b.r;
    const distSq = dx * dx + dy * dy;
    if (distSq >= minDist * minDist) return;
    const invSum = a.invMass + b.invMass;
    if (invSum === 0) return;

    let dist = Math.sqrt(distSq);
    let nx, ny;
    if (dist < 1e-6) {
      // Perfectly stacked: push apart in a random direction.
      const angle = this.rng() * Math.PI * 2;
      nx = Math.cos(angle);
      ny = Math.sin(angle);
      dist = 0;
    } else {
      nx = dx / dist;
      ny = dy / dist;
    }

    // Positional correction, weighted by inverse mass.
    const correction = Math.max(0, minDist - dist - SLOP) / invSum;
    a.x -= nx * correction * a.invMass;
    a.y -= ny * correction * a.invMass;
    b.x += nx * correction * b.invMass;
    b.y += ny * correction * b.invMass;
    this.#keepInside(a);
    this.#keepInside(b);

    // Impulse along the contact normal.
    const rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
    if (rel >= 0) return; // already separating
    const j = (-(1 + e) * rel) / invSum;
    a.vx = clampSpeed(a.vx - j * nx * a.invMass);
    a.vy = clampSpeed(a.vy - j * ny * a.invMass);
    b.vx = clampSpeed(b.vx + j * nx * b.invMass);
    b.vy = clampSpeed(b.vy + j * ny * b.invMass);

    const impact = Math.min(0.35, -rel / 4000);
    const angle = Math.atan2(ny, nx);
    if (impact > a.squash) { a.squash = impact; a.squashAngle = angle; }
    if (impact > b.squash) { b.squash = impact; b.squashAngle = angle + Math.PI; }
  }

  /**
   * Reflect one velocity component off a wall.
   * @param {Ball} b
   * @param {number} speed speed into the wall (positive)
   * @param {number} angle wall normal direction, for the squash effect
   * @param {number} e restitution
   * @param {'x' | 'y'} axis
   */
  #bounce(b, speed, angle, e, axis) {
    if (axis === 'x') b.vx = -b.vx * e;
    else b.vy = -b.vy * e;
    const impact = Math.min(0.35, speed / 4000);
    if (impact > b.squash) {
      b.squash = impact;
      b.squashAngle = angle;
    }
  }

  /** @param {Ball} b */
  #keepInside(b) {
    b.x = this.width >= 2 * b.r ? Math.min(Math.max(b.x, b.r), this.width - b.r) : this.width / 2;
    b.y = this.height >= 2 * b.r ? Math.min(Math.max(b.y, b.r), this.height - b.r) : this.height / 2;
  }

  #randomRadius() {
    const base = this.settings.ballSize;
    return Math.max(4, base * (0.6 + this.rng() * 0.8));
  }
}

/** @param {number} v */
function clampSpeed(v) {
  return Math.max(-MAX_SPEED, Math.min(MAX_SPEED, v));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { World, PX_PER_METER, FIXED_DT, MAX_BALLS, MAX_SPEED } from '../site/js/physics.js';

/** Deterministic PRNG (mulberry32) so tests are repeatable. */
function seeded(seed = 1) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const run = (world, seconds) => {
  for (let i = 0; i < Math.round(seconds / FIXED_DT); i++) world.step(FIXED_DT);
};

const maxOverlap = (balls) => {
  let worst = 0;
  for (let i = 0; i < balls.length; i++)
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i], b = balls[j];
      worst = Math.max(worst, a.r + b.r - Math.hypot(a.x - b.x, a.y - b.y));
    }
  return worst;
};

test('a dropped ball falls at the configured gravity', () => {
  const world = new World({ width: 800, height: 100000, settings: { gravity: 1.62, airDrag: 0 }, rng: seeded() });
  const ball = world.addBall({ x: 400, y: 100, r: 10 });
  run(world, 1);
  const expectedVy = 1.62 * PX_PER_METER; // v = g·t
  assert.ok(Math.abs(ball.vy - expectedVy) < 0.5, `vy=${ball.vy}, expected ≈${expectedVy}`);
  const expectedDrop = 0.5 * expectedVy; // d = ½·g·t²
  assert.ok(Math.abs(ball.y - 100 - expectedDrop) < 2, `drop=${ball.y - 100}`);
});

test('zero gravity leaves a still ball still', () => {
  const world = new World({ width: 800, height: 600, settings: { gravity: 0 }, rng: seeded() });
  const ball = world.addBall({ x: 400, y: 300, r: 10 });
  run(world, 2);
  assert.equal(ball.x, 400);
  assert.equal(ball.y, 300);
});

test('a bounce off the floor keeps the bounciness fraction of the speed', () => {
  const world = new World({ width: 800, height: 600, settings: { gravity: 0, bounciness: 0.8, airDrag: 0 }, rng: seeded() });
  const ball = world.addBall({ x: 400, y: 500, vy: 1000, r: 10 });
  run(world, 0.2);
  assert.ok(ball.vy < 0, 'ball should be moving up after the bounce');
  assert.ok(Math.abs(ball.vy + 800) < 1, `vy=${ball.vy}`);
});

test('balls never leave the world or overlap after settling', () => {
  const world = new World({ width: 900, height: 480, settings: { gravity: 9.81 }, rng: seeded(7) });
  world.spawn(80);
  run(world, 8);
  for (const b of world.balls) {
    assert.ok(Number.isFinite(b.x) && Number.isFinite(b.y), 'position is finite');
    assert.ok(b.x >= b.r - 1e-6 && b.x <= 900 - b.r + 1e-6, `x=${b.x}`);
    assert.ok(b.y >= b.r - 1e-6 && b.y <= 480 - b.r + 1e-6, `y=${b.y}`);
  }
  assert.ok(maxOverlap(world.balls) < 1.5, `overlap=${maxOverlap(world.balls)}`);
});

test('a pile of balls comes to rest under gravity', () => {
  const world = new World({ width: 600, height: 400, settings: { gravity: 9.81, bounciness: 0.7 }, rng: seeded(3) });
  world.spawn(30);
  run(world, 20);
  const fastest = Math.max(...world.balls.map((b) => Math.hypot(b.vx, b.vy)));
  assert.ok(fastest < 30, `fastest ball still moving at ${fastest}px/s`);
});

test('a head-on elastic collision between equal balls swaps their velocities', () => {
  const world = new World({ width: 2000, height: 600, settings: { gravity: 0, bounciness: 1, airDrag: 0 }, rng: seeded() });
  const a = world.addBall({ x: 900, y: 300, vx: 300, r: 20 });
  const b = world.addBall({ x: 1100, y: 300, vx: -300, r: 20 });
  run(world, 0.5);
  assert.ok(Math.abs(a.vx + 300) < 1, `a.vx=${a.vx}`);
  assert.ok(Math.abs(b.vx - 300) < 1, `b.vx=${b.vx}`);
});

test('perfectly elastic collisions with no gravity or drag conserve energy', () => {
  const world = new World({ width: 1000, height: 800, settings: { gravity: 0, bounciness: 1, airDrag: 0 }, rng: seeded(11) });
  world.spawn(25);
  const before = world.kineticEnergy();
  run(world, 3);
  const after = world.kineticEnergy();
  assert.ok(Math.abs(after - before) / before < 0.01, `energy changed from ${before} to ${after}`);
});

test('the ball count is capped, dropping the oldest first', () => {
  const world = new World({ width: 2000, height: 2000, rng: seeded() });
  const first = world.addBall({ x: 10, y: 10, r: 5 });
  for (let i = 0; i < MAX_BALLS + 10; i++) world.addBall({ x: 500, y: 500, r: 5 });
  assert.equal(world.balls.length, MAX_BALLS);
  assert.ok(!world.balls.includes(first));
});

test('a held ball follows the pointer and is thrown on release', () => {
  const world = new World({ width: 1000, height: 600, settings: { gravity: 9.81 }, rng: seeded() });
  const ball = world.addBall({ x: 200, y: 300, r: 20 });
  world.grab(ball, 200, 300, 0);
  // Drag right at 1000 px/s for 0.2 s.
  for (let i = 1; i <= 12; i++) {
    world.dragTo(200 + (i * 1000) / 60, 300, i / 60);
    run(world, 1 / 60);
  }
  assert.ok(Math.abs(ball.x - 400) < 1, `x=${ball.x}`);
  assert.ok(Math.abs(ball.y - 300) < 1, 'gravity does not pull a held ball');
  world.release(12 / 60);
  assert.ok(ball.vx > 700 && ball.vx <= MAX_SPEED, `throw vx=${ball.vx}`);
  assert.ok(ball.invMass > 0, 'released ball is movable again');
});

test('releasing after holding still drops the ball gently', () => {
  const world = new World({ width: 1000, height: 600, rng: seeded() });
  const ball = world.addBall({ x: 200, y: 300, r: 20 });
  world.grab(ball, 200, 300, 0);
  world.dragTo(400, 300, 0.05);
  world.release(1); // pointer idle for almost a second
  assert.equal(ball.vx, 0);
});

test('resizing pulls balls back inside', () => {
  const world = new World({ width: 1000, height: 600, rng: seeded() });
  const ball = world.addBall({ x: 950, y: 550, r: 20 });
  world.setSize(400, 300);
  assert.equal(ball.x, 380);
  assert.equal(ball.y, 280);
});

test('advance runs fixed steps and caps catch-up after a long pause', () => {
  const world = new World({ width: 800, height: 600, rng: seeded() });
  assert.equal(world.advance(FIXED_DT * 4 + 1e-9), 4);
  assert.ok(world.advance(10) <= Math.ceil(0.1 / FIXED_DT));
});

test('reset spawns the starting count of balls inside the world', () => {
  const world = new World({ width: 800, height: 600, settings: { startCount: 15 }, rng: seeded() });
  world.reset();
  assert.equal(world.balls.length, 15);
});

test('ballAt finds the topmost ball under a point', () => {
  const world = new World({ width: 800, height: 600, rng: seeded() });
  world.addBall({ x: 100, y: 100, r: 30 });
  const top = world.addBall({ x: 110, y: 100, r: 30 });
  assert.equal(world.ballAt(105, 100), top);
  assert.equal(world.ballAt(500, 500), null);
});

