*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -48px;
  z-index: 10;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--accent);
  color: var(--accent-text);
  text-decoration: none;
}
.skip-link:focus { top: 12px; }

/* Header */

.site-header {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: var(--header-h);
  padding: 10px max(16px, env(safe-area-inset-right)) 10px max(16px, env(safe-area-inset-left));
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: inherit;
  text-decoration: none;
}
.brand-name { font-size: 18px; font-weight: 650; letter-spacing: -0.01em; }

.tagline { margin: 0; color: var(--muted); }

.header-actions { margin-left: auto; display: flex; gap: 8px; }

/* Buttons */

.btn {
  font: inherit;
  font-weight: 550;
  line-height: 1.2;
  padding: 8px 14px;
  min-height: 38px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  transition: background-color 120ms, border-color 120ms;
}
.btn:hover { background: var(--surface-2); }
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}
.btn-primary:hover { background: var(--accent); filter: brightness(1.08); }

.btn-ghost { background: transparent; border-color: transparent; }

.btn-link {
  background: none;
  border: none;
  padding: 4px 0;
  min-height: 0;
  color: var(--muted);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.btn-link:hover { background: none; color: var(--text); }

/* Layout */

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 16px;
  padding: 16px;
  min-height: 0;
}

.stage {
  position: relative;
  min-height: 420px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--stage-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

#canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  /* Theme tokens read by the renderer */
  --stage-floor: inherit;
}
#canvas.can-grab { cursor: grab; }
#canvas.grabbing { cursor: grabbing; }
#canvas:focus-visible { outline-offset: -3px; border-radius: var(--radius); }

.stage-hint,
.stage-badge,
.stage-noscript {
  position: absolute;
  margin: 0;
  pointer-events: none;
}

.stage-hint {
  left: 50%;
  top: 14px;
  transform: translateX(-50%);
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 13px;
  white-space: nowrap;
  transition: opacity 400ms;
}
.stage-hint.is-hidden { opacity: 0; }

.stage-badge {
  right: 14px;
  top: 14px;
  padding: 4px 10px;
  border-radius: 6px;
  background: var(--text);
  color: var(--bg);
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.stage-noscript { inset: 0; display: grid; place-items: center; padding: 24px; text-align: center; color: var(--muted); }

/* Control panel */

.panel {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px 18px 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  overflow-y: auto;
}

.group {
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.group:last-of-type { border-bottom: none; }

.group h2 {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.presets {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 4px;
  padding: 3px;
  margin-bottom: 12px;
  border-radius: 9px;
  background: var(--surface-2);
}

.preset {
  font: inherit;
  font-size: 13px;
  font-weight: 550;
  padding: 6px 2px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  white-space: nowrap;
}
.preset:hover { color: var(--text); }
.preset[aria-pressed="true"] {
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
}

.field + .field { margin-top: 12px; }

.field-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}
.field-head label { font-weight: 500; }
.field-head output {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

input[type="range"] {
  width: 100%;
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.button-row .btn { flex: 1 1 0; }
.group-actions .button-row { margin-top: 0; }
.group-actions .btn-link { margin-top: 10px; }

.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 6px 0 0;
}
.stats div {
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--surface-2);
}
.stats dt { font-size: 12px; color: var(--muted); }
.stats dd { margin: 0; font-size: 20px; font-weight: 600; font-variant-numeric: tabular-nums; }

/* Footer */

.site-footer {
  padding: 0 16px 16px;
  color: var(--muted);
  font-size: 13px;
}
.site-footer p { margin: 0; }

/* Dialog */

dialog {
  width: min(420px, calc(100vw - 32px));
  padding: 22px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}
dialog::backdrop { background: rgba(10, 12, 16, 0.45); }
dialog h2 { margin: 0 0 14px; font-size: 18px; }

.shortcut-list { margin: 0 0 18px; display: grid; gap: 8px; }
.shortcut-list div { display: flex; gap: 12px; align-items: baseline; }
.shortcut-list dt { min-width: 76px; }
.shortcut-list dd { margin: 0; color: var(--muted); }

kbd {
  display: inline-block;
  min-width: 24px;
  padding: 1px 6px;
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--surface-2);
  font: 12px/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  text-align: center;
}

/* Toast */

.toast {
  position: fixed;
  left: 50%;
  bottom: max(20px, env(safe-area-inset-bottom));
  z-index: 20;
  padding: 10px 16px;
  border-radius: 10px;
  background: var(--text);
  color: var(--bg);
  font-weight: 550;
  box-shadow: var(--shadow);
  transform: translate(-50%, 12px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms, transform 180ms;
}
.toast.is-visible { opacity: 1; transform: translate(-50%, 0); }

/* Responsive */

@media (max-width: 900px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
  .stage { min-height: 0; height: 58vh; height: 58svh; }
  .panel { overflow: visible; }
  .tagline { display: none; }
}

@media (max-width: 420px) {
  .header-actions #shortcuts-btn { display: none; }
  .preset { font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; }
}

