const c = document.getElementById('canvas'); const r = c.getBoundingClientRect();
const ev = (type, x, y) => c.dispatchEvent(new PointerEvent(type, {bubbles: true, pointerId: 7, button: 0, pointerType: 'mouse', clientX: r.left + x, clientY: r.top + y}));
// Drop a ball into empty space, then grab it right away and throw it right.
const before = document.getElementById('stat-balls').textContent;
ev('pointerdown', 40, r.height - 30); ev('pointerup', 40, r.height - 30);
await new Promise(res => setTimeout(res, 50));
ev('pointerdown', 40, r.height - 30);
const grabbing = c.classList.contains('grabbing');
for (let i = 1; i <= 8; i++) { ev('pointermove', 40 + i * 15, r.height - 30 - i * 10); await new Promise(res => setTimeout(res, 16)); }
ev('pointerup', 160, r.height - 110);
const stillGrabbing = c.classList.contains('grabbing');
document.getElementById('defaults-btn').click();
await new Promise(res => setTimeout(res, 300));
({ grabbing, releasedOk: !stillGrabbing, hashAfterDefaults: location.hash, gravityAfterDefaults: document.getElementById('gravity-out').textContent, hint: document.getElementById('hint').textContent, toast: document.getElementById('toast').textContent })
